 p=[0]
 for i in range(14):
  if mask>>i&1:p +=[x^(1<<i) for x in p]
 return p
A=127;B=(N-1)^A
found={}
for a,b,d,e in itertools.product(range(8),repeat=4):
 if not(0<=d<=min(a,b) and a+b-d<=7 and 0<=e<=min(7-a,7-b) and 14-a-b-e<=7):continue
 w=510-2*((1<<a)+(1<<(7-a))+(1<<b)+(1<<(7-b))+(1<<(d+e))-2*(1<<d)-2*(1<<e))
